const PRISM_WHATSAPP_URL=''; // Add the official Prism Edu WhatsApp URL when available.
const emptyLandFilters={search:'',type:'All',transaction:'All Transactions',location:''};
function filterLands(items,filters){const query=filters.search.trim().toLowerCase(),place=filters.location.trim().toLowerCase();return items.filter(item=>(!query||[item.title,item.location,item.area,item.suitability,item.description,item.transaction].join(' ').toLowerCase().includes(query))&&(!place||item.location.toLowerCase().includes(place))&&(filters.type==='All'||(filters.type==='Land Available'&&item.type==='available')||(filters.type==='Land Required'&&item.type==='required'))&&(filters.transaction==='All Transactions'||item.transaction.toLowerCase().includes(filters.transaction.toLowerCase())));}

function LandFilters({filters,setFilters}){const update=(key,value)=>setFilters({...filters,[key]:value});return <form onSubmit={e=>e.preventDefault()} className="mb-9 rounded-2xl border border-white bg-white/90 p-4 shadow-[0_16px_45px_rgba(16,38,63,.08)]"><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-5"><label className="relative lg:col-span-2"><span className="sr-only">Search land listings</span><Search size={17} className="absolute left-3 top-3.5 text-slate-400"/><input className="field pl-10" value={filters.search} onChange={e=>update('search',e.target.value)} placeholder="Search school land..."/></label><select className="field" aria-label="Listing type" value={filters.type} onChange={e=>update('type',e.target.value)}><option>All</option><option>Land Available</option><option>Land Required</option></select><select className="field" aria-label="Transaction type" value={filters.transaction} onChange={e=>update('transaction',e.target.value)}><option>All Transactions</option><option>Sale</option><option>Rent</option><option>Lease</option></select><input className="field" value={filters.location} onChange={e=>update('location',e.target.value)} placeholder="Search by city / location"/></div><div className="mt-3 flex justify-end gap-2"><button className="btn !px-4 !py-2">Search</button><button type="button" className="btn2 !px-4 !py-2" onClick={()=>setFilters(emptyLandFilters)}>Clear Filters</button></div></form>}

function SchoolLandMarketplace(){
  const[index,setIndex]=useState(0),[paused,setPaused]=useState(false),[perView,setPerView]=useState(3),[touchStart,setTouchStart]=useState(null),[filters,setFilters]=useState(emptyLandFilters);
  useEffect(()=>{const resize=()=>setPerView(innerWidth<640?1:innerWidth<1024?2:3);resize();addEventListener('resize',resize);return()=>removeEventListener('resize',resize)},[]);
  const filtered=useMemo(()=>filterLands(landSlides.filter(x=>x.active&&x.featured),filters),[filters]);useEffect(()=>setIndex(0),[filters]);useEffect(()=>{if(paused||!filtered.length)return;const timer=setTimeout(()=>setIndex(i=>(i+1)%filtered.length),5500);return()=>clearTimeout(timer)},[paused,index,filtered.length]);
  const move=step=>filtered.length&&setIndex(i=>(i+step+filtered.length)%filtered.length),visible=filtered.length?Array.from({length:Math.min(perView,filtered.length)},(_,i)=>filtered[(index+i)%filtered.length]):[];
  return <section className="overflow-hidden bg-cream py-16 md:py-20" aria-labelledby="land-marketplace-title"><div className="wrap">
    <div className="mx-auto mb-9 max-w-4xl text-center"><span className="eyebrow">SCHOOL LAND MARKETPLACE</span><h2 id="land-marketplace-title" className="title">School Land Marketplace</h2><p className="mt-4 text-lg leading-8">Find suitable land for your school or list your property for Rent / Sale for School / Education Purpose.</p></div><LandFilters filters={filters} setFilters={setFilters}/>
    <div className="relative" onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)} onTouchStart={e=>setTouchStart(e.touches[0].clientX)} onTouchEnd={e=>{if(touchStart===null)return;const distance=e.changedTouches[0].clientX-touchStart;if(Math.abs(distance)>45)move(distance<0?1:-1);setTouchStart(null)}}>
      {visible.length?<div className="grid gap-5 transition-all duration-500 sm:grid-cols-2 lg:grid-cols-3" aria-live="polite">{visible.map((land,slot)=><LandMarketCard key={land.id+'-'+slot} land={land}/>)}</div>:<div className="rounded-2xl border bg-white p-10 text-center"><Search className="mx-auto mb-3 text-slate-300"/><h3>No matching land listings</h3><p className="mt-2 text-sm">Clear filters or submit your land requirement.</p></div>}
      <button type="button" onClick={()=>move(-1)} className="absolute left-0 top-1/2 grid h-10 w-10 -translate-x-2 -translate-y-1/2 place-items-center rounded-full border bg-white text-ink shadow-md transition hover:border-gold sm:-translate-x-5" aria-label="Previous land opportunity"><ChevronLeft size={19}/></button>
      <button type="button" onClick={()=>move(1)} className="absolute right-0 top-1/2 grid h-10 w-10 translate-x-2 -translate-y-1/2 place-items-center rounded-full border bg-white text-ink shadow-md transition hover:border-gold sm:translate-x-5" aria-label="Next land opportunity"><ChevronRight size={19}/></button>
    </div>
    <div className="mt-7 flex justify-center gap-2" aria-label="Choose slide">{filtered.map((land,i)=><button key={land.id} onClick={()=>setIndex(i)} aria-label={'Show '+land.location} className={'h-2 rounded-full transition-all '+(i===index?'w-7 bg-gold':'w-2 bg-slate-300 hover:bg-slate-400')}/>)}</div>
    <div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Link className="btn" to="/school-land/requirement">Require School Land <ArrowRight size={16}/></Link><Link className="btn" to="/school-land/list">List Land for School — Rent / Sale <ArrowRight size={16}/></Link>{PRISM_WHATSAPP_URL?<a className="btn2" href={PRISM_WHATSAPP_URL} target="_blank" rel="noreferrer">Contact Immediately</a>:<Link className="btn2" to="/contact">Contact Immediately</Link>}<Link className="btn2" to="/school-land">View All School Land <ArrowRight size={16}/></Link></div>
  </div></section>
}

function LandMarketCard({land}){const required=land.type==='required';return <Link to={'/school-land/'+land.id} className={'group flex min-h-[310px] flex-col rounded-2xl border-t-4 p-6 shadow-[0_16px_45px_rgba(16,38,63,.08)] transition hover:-translate-y-1 hover:shadow-xl '+(required?'border-amber-500 bg-amber-50/70':'border-emerald-600 bg-emerald-50/70')}><div className="flex items-start justify-between gap-3"><div className={'grid h-11 w-11 place-items-center rounded-lg bg-white '+(required?'text-amber-700':'text-emerald-700')}>{required?<Search size={21}/>:<LandPlot size={21}/>}</div><div className="flex flex-wrap justify-end gap-1.5">{land.badges.map(b=><span key={b} className={'rounded-full px-2 py-1 text-[9px] font-bold tracking-wider '+(b==='URGENT'?'bg-red-600 text-white':required?'bg-amber-600 text-white':'bg-emerald-700 text-white')}>{b}</span>)}</div></div><p className="mt-5 text-[10px] font-bold uppercase tracking-[.16em] text-slate-500">{required?'Land Required':'Land Available'}</p><h3 className="mt-1 text-lg">{land.title}</h3><div className="mt-4 grid gap-3 text-sm"><p className="flex gap-2"><MapPin size={16} className="shrink-0 text-gold"/>{land.location}</p><p className="flex gap-2"><Ruler size={16} className="shrink-0 text-gold"/>{land.area}</p><p className="flex gap-2"><IndianRupee size={16} className="shrink-0 text-gold"/>{land.transaction}</p><p className="flex gap-2"><Road size={16} className="shrink-0 text-gold"/>{land.roadConnectivity}</p></div><span className="mt-auto inline-flex items-center gap-1 pt-5 text-sm font-bold text-ink group-hover:text-gold">View Details <ArrowRight size={15}/></span></Link>}

function SchoolLandPage(){const[filters,setFilters]=useState(emptyLandFilters),[limit,setLimit]=useState(6),items=useMemo(()=>filterLands(landSlides.filter(x=>x.active),filters),[filters]);return <><Hero label="SCHOOL LAND MARKETPLACE" title="Find or List School Land" text="Search active school-land opportunities and requirements by location and transaction type."/><section className="bg-cream py-16"><div className="wrap"><LandFilters filters={filters} setFilters={setFilters}/><p className="mb-5 text-sm text-slate-500">Showing {Math.min(limit,items.length)} of {items.length} listings</p><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{items.slice(0,limit).map(x=><LandMarketCard land={x} key={x.id}/>)}</div>{limit<items.length&&<div className="mt-9 text-center"><button className="btn2" onClick={()=>setLimit(x=>x+6)}>Load More</button></div>}</div></section></>}

function LandDetails(){const{id}=useParams(),land=landSlides.find(x=>x.id===id);if(!land)return <Hero label="NOT FOUND" title="Land listing not found" text="This listing may no longer be active."/>;const required=land.type==='required',Icon=required?Search:LandPlot;return <><section className="bg-cream py-14"><div className="wrap grid gap-10 lg:grid-cols-2"><div className="grid min-h-[360px] place-items-center rounded-2xl border bg-white shadow-sm">{land.images?.[0]?<img src={land.images[0]} alt={land.title} className="h-full w-full rounded-2xl object-cover"/>:<Icon size={100} className={required?'text-amber-500':'text-emerald-600'}/>}</div><div><span className="eyebrow">{required?'LAND REQUIRED':'LAND AVAILABLE'}</span><h1 className="title">{land.title}</h1><div className="mt-4 flex gap-2">{land.badges.map(x=><span key={x} className="rounded-full bg-white px-3 py-1 text-[10px] font-bold">{x}</span>)}</div><p className="mt-6 leading-7">{land.description}</p><dl className="mt-6 grid grid-cols-2 gap-4 text-sm">{[['Location',land.location],['Area',land.area],['Transaction',land.transaction],['Suitability',land.suitability],['Road connectivity',land.roadConnectivity],['Expected price / rent',land.price]].filter(x=>x[1]).map(([k,v])=><div key={k}><dt className="text-slate-400">{k}</dt><dd className="font-bold text-ink">{v}</dd></div>)}</dl><div className="mt-7 flex flex-wrap gap-3"><Link className="btn" to="/contact">Get Details</Link>{PRISM_WHATSAPP_URL?<a className="btn2" href={PRISM_WHATSAPP_URL} target="_blank" rel="noreferrer">Contact Immediately</a>:<Link className="btn2" to="/contact">Contact Immediately</Link>}{land.mapUrl&&<a className="btn2" href={land.mapUrl} target="_blank" rel="noreferrer"><MapPin size={16}/>View on Map</a>}</div></div></div></section></>}

