function ServicesSlideshow(){
  const[index,setIndex]=useState(0),[paused,setPaused]=useState(false),[perView,setPerView]=useState(3),[touchStart,setTouchStart]=useState(null);
  useEffect(()=>{const resize=()=>setPerView(innerWidth<640?1:innerWidth<1024?2:3);resize();addEventListener('resize',resize);return()=>removeEventListener('resize',resize)},[]);
  useEffect(()=>{if(paused)return;const timer=setTimeout(()=>setIndex(i=>(i+1)%serviceSlides.length),5500);return()=>clearTimeout(timer)},[paused,index]);
  const move=step=>setIndex(i=>(i+step+serviceSlides.length)%serviceSlides.length);
  const visible=Array.from({length:perView},(_,i)=>serviceSlides[(index+i)%serviceSlides.length]);
  return <section className="relative overflow-hidden bg-gradient-to-br from-[#f4f7fc] via-[#faf7f1] to-[#f5f1fb] py-16 md:py-24" aria-labelledby="consultancy-services-title"><div className="absolute -left-32 top-10 h-80 w-80 rounded-full bg-indigo-200/20 blur-3xl"/><div className="absolute -right-28 bottom-0 h-72 w-72 rounded-full bg-gold/10 blur-3xl"/><div className="wrap relative">
    <div className="mx-auto mb-11 max-w-4xl text-center"><span className="eyebrow">OUR SERVICES</span><h2 id="consultancy-services-title" className="text-4xl font-extrabold leading-tight tracking-tight text-ink md:text-5xl">Complete School <span className="text-gold">Consultancy Services</span></h2><p className="mx-auto mt-4 max-w-3xl text-base leading-7 text-slate-600 md:text-lg">From school idea to establishment, licensing, branding, admissions, restructuring and growth — Prism Edu supports schools at every stage.</p></div>
    <div className="relative" onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)} onTouchStart={e=>setTouchStart(e.touches[0].clientX)} onTouchEnd={e=>{if(touchStart===null)return;const distance=e.changedTouches[0].clientX-touchStart;if(Math.abs(distance)>45)move(distance<0?1:-1);setTouchStart(null)}}>
      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3" aria-live="polite">{visible.map((service,slot)=><ServiceSlideCard key={service.title+'-'+slot} service={service}/>)}</div>
      <button type="button" onClick={()=>move(-1)} className="absolute left-0 top-1/2 grid h-10 w-10 -translate-x-2 -translate-y-1/2 place-items-center rounded-full border bg-white text-ink shadow-md transition hover:border-gold sm:-translate-x-5" aria-label="Previous consultancy service"><ChevronLeft size={19}/></button>
      <button type="button" onClick={()=>move(1)} className="absolute right-0 top-1/2 grid h-10 w-10 translate-x-2 -translate-y-1/2 place-items-center rounded-full border bg-white text-ink shadow-md transition hover:border-gold sm:translate-x-5" aria-label="Next consultancy service"><ChevronRight size={19}/></button>
    </div>
    <div className="mt-7 flex justify-center gap-2" aria-label="Choose service slide">{serviceSlides.map((service,i)=><button key={service.title} onClick={()=>setIndex(i)} aria-label={'Show '+service.title} className={'h-2 rounded-full transition-all '+(i===index?'w-7 bg-gold':'w-2 bg-slate-300 hover:bg-slate-400')}/>)}</div>
    <div className="mt-9 flex flex-col justify-center gap-3 sm:flex-row"><Link className="btn2" to="/services">Explore All Services <ArrowRight size={16}/></Link>{PRISM_CALENDLY_URL?<a className="btn" href={PRISM_CALENDLY_URL} target="_blank" rel="noreferrer">Request Consultation <ArrowRight size={16}/></a>:<Link className="btn" to="/contact">Request Consultation <ArrowRight size={16}/></Link>}</div>
  </div></section>
}

function ServiceSlideCard({service}){const Icon=service.icon,tones={indigo:'bg-indigo-50 text-indigo-700 border-indigo-100',purple:'bg-purple-50 text-purple-700 border-purple-100',blue:'bg-blue-50 text-blue-700 border-blue-100',gold:'bg-amber-50 text-amber-700 border-amber-100',green:'bg-emerald-50 text-emerald-700 border-emerald-100'};return <article className="group flex min-h-[390px] flex-col overflow-hidden rounded-[1.35rem] border border-white/90 bg-white/90 shadow-[0_16px_50px_rgba(16,38,63,.09)] backdrop-blur transition duration-300 hover:-translate-y-1.5 hover:border-gold/40 hover:shadow-[0_22px_60px_rgba(16,38,63,.14)]">
  <div className={'relative grid h-36 place-items-center border-b '+tones[service.accent]}><span className="absolute left-4 top-4 rounded-full border border-current/10 bg-white/80 px-2.5 py-1 text-[9px] font-extrabold tracking-[.14em]">{service.category}</span><div className="grid h-20 w-20 place-items-center rounded-2xl border border-white/80 bg-white/70 shadow-sm transition duration-300 group-hover:-translate-y-1"><Icon size={40}/></div><div className="absolute -bottom-8 -right-8 h-24 w-24 rounded-full border-[16px] border-current opacity-[.06]"/></div><div className="flex flex-1 flex-col p-6">
  <h3 className="text-xl font-bold">{service.title}</h3><p className="mt-3 line-clamp-3 text-sm leading-6 text-slate-600">{service.text}</p><Link to={service.to} className="mt-auto inline-flex items-center gap-1 pt-5 text-sm font-bold text-ink transition group-hover:gap-2 group-hover:text-gold">Explore Service <ArrowRight size={15}/></Link></div>
</article>}

