      <button type="button" onClick={()=>move(-1)} className="absolute left-0 top-1/2 grid h-10 w-10 -translate-x-2 -translate-y-1/2 place-items-center rounded-full border bg-white text-ink shadow-md transition hover:border-gold sm:-translate-x-5" aria-label="Previous school material"><ChevronLeft size={19}/></button>
